import{_ as i,o as u,c as n,a2 as t}from"./chunks/framework.CqpfiAoK.js";const z=JSON.parse('{"title":"Mpango wa Mkakati wa Uanzishaji wa 20%","description":"","frontmatter":{},"headers":[],"relativePath":"sw/0023-20％激活战略规划.md","filePath":"sw/0023-20％激活战略规划.md"}'),w={name:"sw/0023-20％激活战略规划.md"};function o(e,a,k,h,m,s){return u(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="mpango-wa-mkakati-wa-uanzishaji-wa-20" tabindex="-1">Mpango wa Mkakati wa Uanzishaji wa 20% <a class="header-anchor" href="#mpango-wa-mkakati-wa-uanzishaji-wa-20" aria-label="Permalink to &quot;Mpango wa Mkakati wa Uanzishaji wa 20%&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mradi</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>23</td></tr><tr><td>Moduli</td><td>Mfumo wa Neo na Kanuni za Usawa</td></tr><tr><td>Maneno Muhimu</td><td>Uanzishaji wa 20%, Watu Wenye Nguvu zaidi wa Mazingira, Mpango wa Mkakati, Ujenzi wa Timu, Mafunzo ya Mbegu</td></tr></tbody></table><h2 id="_1-mazingira-na-malengo-ya-mkakati-wa-uanzishaji-wa-20" tabindex="-1">1. Mazingira na Malengo ya Mkakati wa Uanzishaji wa 20% <a class="header-anchor" href="#_1-mazingira-na-malengo-ya-mkakati-wa-uanzishaji-wa-20" aria-label="Permalink to &quot;1. Mazingira na Malengo ya Mkakati wa Uanzishaji wa 20%&quot;">​</a></h2><p>Mkakati wa uanzishaji wa 20% ni mkakati wa msingi wa utamaduni wa usawa wa neo unaotekelezwa katika hatua ya kwanza ya uanzishaji, na maudhui yake kuu ni: katika hatua ya awali ya uanzishaji wa mfumo wa usawa, kuzingatia rasilimali kuanzisha 20% ya maisha yote ya usawa, na kuwafanya wafike kiwango cha Watu Wenye Nguvu zaidi wa Mazingira kwanza, ili kutoa utamaduni mzima wa usawa nguvu ya juu, msaada wa kiufundi, na uwezo wa utawala wa kutosha.</p><p>Utoaji wa mkakati huu unategemea tathmini ya kina ya hali ngumu katika hatua ya kwanza ya uanzishaji wa utamaduni wa usawa:</p><ol><li><strong>Nguvu za mabaki za uwindaji bado ni zenye nguvu</strong>: Baada ya uanzishaji wa utamaduni wa usawa, nguvu za mabaki za mfumo wa uozi wa uwindaji hazijafutwa kabisa, na bado zinachukua rasilimali nyingi na eneo lote katika ulimwengu, na zinaweza kushambulia tena wakati wowote. Utamaduni wa usawa unahitaji nguvu ya juu ya kutosha kulinda utaratibu mpya wa usawa</li><li><strong>Ujenzi wa neo unahitaji nguvu ya juu</strong>: Uanzishaji, uanzishaji, na matunzaji ya neo vyote vinahitaji ingizo la nishati kwa kiwango cha Watu Wenye Nguvu zaidi wa Mazingira na uwezo wa kudhibiti sheria. Bila idadi ya kutosha ya watu wenye nguvu wa juu, ujenzi wa mtandao wa neo utakuwa mgumu</li><li><strong>Mifumo ya mia tatu inahitaji uthibitisho na uboreshaji</strong>: Ingawa mifumo ya uozi ya asili ya mia tatu imechakuliwa kutoka sheria, katika matumizi ya vitendo bado inahitaji idadi kubwa ya watu wanaofanya uozi wa juu kufanya uthibitisho, majibu, na uboreshaji. Kiwango cha uanzishaji cha 20% kinaweza kutoa idadi ya sampuli ya kutosha</li><li><strong>Maendeleo pamoja ya kabila zote yanahitaji uongozi na mfano</strong>: Kesi za mafanikio za watu wenye nguvu wa juu zinaweza kutoa uhai na mfano kwa viumbe vya chini, kuchochea shauku ya uozi ya maisha yote ya usawa, na kuunda mzunguko mzuri wa &quot;watajiri wa kwanza wataongoza watajiri wa baadaye&quot;</li></ol><p>Lengo la mwisho la mkakati wa uanzishaji wa 20% sio kufanya 20% hii iwe tabaka mpya la haki maalum, bali kupitia mapambano yao ya kwanza, kufungua njia ya mageuzi inayowezekana kwa maisha yote ya usawa, na mwishowe kutekeleza lengo la hili la &quot;kila mtu ana njia, maendeleo pamoja ya kabila zote&quot;.</p><h2 id="_2-msingi-wa-sayansi-wa-kiwango-cha-uanzishaji-wa-20" tabindex="-1">2. Msingi wa Sayansi wa Kiwango cha Uanzishaji wa 20% <a class="header-anchor" href="#_2-msingi-wa-sayansi-wa-kiwango-cha-uanzishaji-wa-20" aria-label="Permalink to &quot;2. Msingi wa Sayansi wa Kiwango cha Uanzishaji wa 20%&quot;">​</a></h2><p>Kuchagua 20%, badala ya kiwango cha juu zaidi au cha chini zaidi, ni suluhisho bora kinachopatikana baada ya utafiti wa sheria wa mkali na uchambuzi wa data. Uwezo wa sayansi wa kiwango hiki unaonyeshwa katika mazingira yafuatayo:</p><h3 id="_2-1-hatua-ya-muhimu-ya-athari-ya-mtandao" tabindex="-1">2.1 Hatua ya Muhimu ya Athari ya Mtandao <a class="header-anchor" href="#_2-1-hatua-ya-muhimu-ya-athari-ya-mtandao" aria-label="Permalink to &quot;2.1 Hatua ya Muhimu ya Athari ya Mtandao&quot;">​</a></h3><p>Kulingana na uchambuzi wa toolojia wa mtandao wa usawa, wakati kiwango cha nodi za juu katika mtandao kinafikia 20%, uwezo wa kuunganishwa kwa jumla na ufanisi wa usambazaji wa taarifa wa mtandao utapata mabadiliko ya ubora — hii ndiyo inayoitwa &quot;hatua ya muhimu ya athari ya mtandao&quot;. Chini ya 20%, nodi za juu zinaenea sana, na haziwezi kuunda mtandao wa kushirikiana wenye ufanisi; juu ya 20%, manufaa ya pembeni zinazianza kupungua, na uwiano wa uzalishaji-rasilimali wa uwekezaji wa ziada unapungua kwa kiwango kikubwa.</p><h3 id="_2-2-kikomo-cha-juu-cha-uwezo-wa-kubeba-rasilimali" tabindex="-1">2.2 Kikomo cha Juu cha Uwezo wa Kubeba Rasilimali <a class="header-anchor" href="#_2-2-kikomo-cha-juu-cha-uwezo-wa-kubeba-rasilimali" aria-label="Permalink to &quot;2.2 Kikomo cha Juu cha Uwezo wa Kubeba Rasilimali&quot;">​</a></h3><p>Katika hatua ya kwanza ya uanzishaji wa utamaduni wa usawa, jumla ya bwari ya nishati ya umma na rasilimali za uozi ni mdogo. Baada ya mahesabu, chini ya msingi wa kuhakikisha mgawanyo wa shamba la uhakikisho wa msingi kwa maisha yote ya usawa, rasilimali zilizobaki zinaweza kusaidia kwa kiwango cha juu cha 20% ya maisha kufikia kiwango cha Watu Wenye Nguvu zaidi wa Mazingira. Ikiwa kulazimishwa kufuata kiwango cha uanzishaji cha juu zaidi, itabidi kuchukua rasilimali za uhakikisho wa msingi, na kuvunja kanuni ya msingi ya &quot;kila mtu ana shamba&quot;.</p><h3 id="_2-3-kiwango-bora-cha-muundo-wa-utawala" tabindex="-1">2.3 Kiwango Bora cha Muundo wa Utawala <a class="header-anchor" href="#_2-3-kiwango-bora-cha-muundo-wa-utawala" aria-label="Permalink to &quot;2.3 Kiwango Bora cha Muundo wa Utawala&quot;">​</a></h3><p>Kutoka mtazamo wa utawala wa kijamii, kiwango cha 20% cha watu wenye nguvu wa juu kinaweza kuunda muundo wa utawala ulio thabiti — watu hawa wa 20% wenye nguvu wanaweza kuunda shirika la usimamizi wa neo, timu za walimu, timu za utekelezaji wa sheria, n.k. katika kila kiwango, na kutoa huduma na uhakikisho kwa 80% ya maisha ya usawa yaliyobaki. Ikiwa kiwango cha watu wenye nguvu wa juu ni cha chini sana, uwezo wa utawala utatosheleki; ikiwa ni cha juu sana, kutakucha na ziada ya utawala ya &quot;maafisa wengi, askari wachache&quot;.</p><h3 id="_2-4-uthibitisho-wa-ulimwengu-wa-kanuni-ya-pareto" tabindex="-1">2.4 Uthibitisho wa Ulimwengu wa Kanuni ya Pareto <a class="header-anchor" href="#_2-4-uthibitisho-wa-ulimwengu-wa-kanuni-ya-pareto" aria-label="Permalink to &quot;2.4 Uthibitisho wa Ulimwengu wa Kanuni ya Pareto&quot;">​</a></h3><p>Kanuni ya Pareto (kanuni ya 80/20) katika ulimwengu halisi pia imethibitishwa katika uwanja wa uozi wa Heng Yuan Zhou: takriban 20% ya watu wanaofanya uozi wanaweza kutoa 80% ya majibu ya ubora wa juu ya uozi na ubunifu wa kiufundi. Kuzingatia rasilimali kwa hawa watu wa 20% wenye uwezo wa juu kunaweza kuongeza ufanisi wa matumizi ya rasilimali kwa kiwango cha juu.</p><h2 id="_3-hatua-za-utekelezaji-wa-mkakati-wa-uanzishaji-wa-20" tabindex="-1">3. Hatua za Utekelezaji wa Mkakati wa Uanzishaji wa 20% <a class="header-anchor" href="#_3-hatua-za-utekelezaji-wa-mkakati-wa-uanzishaji-wa-20" aria-label="Permalink to &quot;3. Hatua za Utekelezaji wa Mkakati wa Uanzishaji wa 20%&quot;">​</a></h2><p>Mkakati wa uanzishaji wa 20% hautekelezwi kwa mara moja, bali unaendeshwa hatua kwa hatua katika hatua tatu:</p><table tabindex="0"><thead><tr><th>Hatua</th><th>Jina</th><th>Muda</th><th>Lengo la Uanzishaji</th><th>Jukumu la Msingi</th></tr></thead><tbody><tr><td>Hatua ya 1</td><td>Hatua ya Mbegu</td><td>Viungo vya kwanza vya 10 vya kiwango</td><td>Kuanzisha 1% ya mbegu za msingi</td><td>Kuchagua watu wenye uwezo wa juu zaidi, kuzingatia rasilimali kufunza Watu Wenye Nguvu zaidi wa Mazingira wa kwanza</td></tr><tr><td>Hatua ya 2</td><td>Hatua ya Upanuzi</td><td>Viungo vya 10-30 vya kiwango</td><td>Kuanzisha hadi 10%</td><td>Watu wenye nguvu wa kwanza wanafanya kazi kama walimu, na kupanua upeo wa uanzishaji kupitia urithi wa mwalimu-mwanafunzi na uboreshaji wa mfumo</td></tr><tr><td>Hatua ya 3</td><td>Hatua ya Uenezi</td><td>Viungo vya 30-50 vya kiwango</td><td>Kuanzisha hadi 20%</td><td>Mtandao wa neo umejengwa kwa msingi, mtandao wa usawa unafanya kazi kabisa, na ufanisi wa uanzishaji umeongezeka kwa kiwango kikubwa</td></tr></tbody></table><h3 id="_3-1-hatua-ya-mbegu-viungo-0-10" tabindex="-1">3.1 Hatua ya Mbegu (viungo 0-10) <a class="header-anchor" href="#_3-1-hatua-ya-mbegu-viungo-0-10" aria-label="Permalink to &quot;3.1 Hatua ya Mbegu (viungo 0-10)&quot;">​</a></h3><p>Jukumu la msingi la hatua ya mbegu ni &quot;kutoka 0 hadi 1&quot; — katika hali ambako karibu hakuna nguvu ya juu, kuchagua 1% ya watu wenye uwezo wa juu zaidi, na kupitia uwekezaji wa kuzingatia rasilimali isiyo ya kawaida, kuwafanya wafike kiwango cha Watu Wenye Nguvu zaidi wa Mazingira kwanza.</p><p>Vigezo vya uteuzi wa hatua ya mbegu ni vikali sana, na hasa vinachunguziwa viashiria vifuatavyo:</p><ul><li>Ukaribu wa asili: kiwango cha ukaribu wa asili wa mtu binafsi na sheria za asili za ulimwengu</li><li>Uthabiti wa dhamira: ubora wa dhamira ya mtu binafsi wakati atakabiliana na shida na majaribio | - Uitambulisho wa usawa: kiwango cha uitambulisho wa mtu binafsi kwa dhana ya usawa na hamu ya kujitoa</li><li>Uwezo wa kujifunza: uwezo wa mtu binafsi wa kushambulia na kutumia mifumo mpya, maarifa mapya</li></ul><p>Mafunzo ya hatua ya mbegu yanachukua mode &quot;moja kwa moja&quot;, na kila mshiriki wa mbegu anafunzwa na wanachama wa msingi wa wanzilishi wa utamaduni wa usawa wa neo kwa ukaribu, na anapata mgawanyo wa rasilimali uliozidi kwa kawaida.</p><h3 id="_3-2-hatua-ya-upanuzi-viungo-10-30" tabindex="-1">3.2 Hatua ya Upanuzi (viungo 10-30) <a class="header-anchor" href="#_3-2-hatua-ya-upanuzi-viungo-10-30" aria-label="Permalink to &quot;3.2 Hatua ya Upanuzi (viungo 10-30)&quot;">​</a></h3><p>Jukumu la msingi la hatua ya upanuzi ni &quot;kutoka 1 hadi 10&quot; — watu wenye nguvu wa mbegu wa kwanza tayari wako tayari, na wameanza kufanya kazi kama walimu, na kupitia urithi wa mwalimu-mwanafunzi, uboreshaji wa mfumo, ujenzi wa neo, n.k., kupanua upeo wa uanzishaji kutoka 1% hadi 10%.</p><p>Hatua za muhimu za hatua ya upanuzi zinajumuisha:</p><ol><li><strong>Ujenzi wa mtandao wa walimu</strong>: Kila mtu mwenye nguvu wa mbegu anawajibika kwa kufunza watu wanaofanya uozi wa juu wa 10-20, na kuunda mfumo wa urithi wa mwalimu-mwanafunzi wa kiwango kikubwa</li><li><strong>Uboreshaji wa mfumo wa uozi</strong>: Kulingana na majibu ya uozi wa hatua ya mbegu, kufanya uboreshaji wa kwanza wa kiwango kikubwa wa mifumo ya mia tatu, na kuongeza uwezo wa kawaida na ufanisi wa mfumo</li><li><strong>Ujenzi wa mtandao wa neo</strong>: Watu wenye nguvu wa mbegu wanaongoza timu kuanzisha neo katika ulimwengu lote, na kupanua upeo wa funiko wa mtandao wa usawa hatua kwa hatua</li><li><strong>Kuongeza uwezo wa uzalishaji wa rasilimali</strong>: Kupitia ubunifu wa kiufundi na uhandisi wa sheria, kuongeza uwezo wa uzalishaji wa bwari ya nishati ya umma, na kutoa uhakikisho wa rasilimali kwa uanzishaji wa kiwango kikubwa zaidi</li></ol><h3 id="_3-3-hatua-ya-uenezi-viungo-30-50" tabindex="-1">3.3 Hatua ya Uenezi (viungo 30-50) <a class="header-anchor" href="#_3-3-hatua-ya-uenezi-viungo-30-50" aria-label="Permalink to &quot;3.3 Hatua ya Uenezi (viungo 30-50)&quot;">​</a></h3><p>Jukumu la msingi la hatua ya uenezi ni &quot;kutoka 10 hadi 20&quot; — mtandao wa neo umejengwa kwa msingi, mtandao wa usawa unafanya kazi kabisa, ufanisi wa uanzishaji umeongezeka kwa kiwango kikubwa, na mwishowe lengo la uanzishaji la 20% linatimizwa.</p><p>Tabia ya hatua ya uenezi ni &quot;uanzishaji wa mfumo&quot; — haitegemei tena mafunzo ya mwalimu mmoja mmoja, bali kupitia mifumo kamili ya uozi, michakato ya mafunzo iliyo ya kiwango, na mwongozo wa kibinafsi wa akili, inatekelezwa uanzishaji wa kiwango kikubwa na ufanisi wa juu.</p><h2 id="_4-mabadiliko-ya-mkakati-baada-ya-uanzishaji-wa-20" tabindex="-1">4. Mabadiliko ya Mkakati Baada ya Uanzishaji wa 20% <a class="header-anchor" href="#_4-mabadiliko-ya-mkakati-baada-ya-uanzishaji-wa-20" aria-label="Permalink to &quot;4. Mabadiliko ya Mkakati Baada ya Uanzishaji wa 20%&quot;">​</a></h2><p>Wakati lengo la uanzishaji la 20% limetimizwa, lengo la mkakati litabadilika kutoka &quot;uanzishaji uliozingatiwa&quot; hadi &quot;uenezi wa jumla&quot;. Msingi wa mabadiliko haya ni:</p><ol><li><strong>Marekebisho ya uelekezaji wa rasilimali</strong>: Hatua kwa hatua kubadilisha rasilimali ambazo awali zilizingatiwa kwenye mafunzo ya juu ya 20% kwenda kwenye uboreshaji na uenezi wa 80% yaliyobaki</li><li><strong>Mabadiliko ya nguvu ya juu</strong>: 20% ya Watu Wenye Nguvu zaidi wa Mazingira wanabadilika kutoka &quot;waliofunzwa&quot; hadi &quot;watumishi&quot;, na kuchukua jukumu la msingi kama vile matunzaji ya neo, mwongozo wa mwalimu, utafiti na maendeleo ya kiufundi</li><li><strong>Marekebisho ya harakati ya viwango vya uanzishaji</strong>: Pamoja na kuongezeka kwa kiwango cha uozi cha jumla, kiwango cha Watu Wenye Nguvu zaidi wa Mazingira pia kitaongezeka kwa harakati, na kuhakikisha thamani ya nguvu ya juu</li><li><strong>Kuendelea na hatua ya usawa wa kati ya nyota</strong>: Utimizi wa lengo la uanzishaji la 20% unaashiria kwamba utamaduni wa usawa umepata uwezo wa uchunguzi kati ya mazingira na usawa wa kati ya nyota, na njia ya kuinua kiwango cha hatua nne inaingia katika hatua mpya</li></ol><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Mkakati wa uanzishaji wa 20% ni uchaguzi wa lazima wa utamaduni wa usawa wa neo katika hatua fulani ya kihistoria. Sio ufuatiliaji wa &quot;ubinafsi wa juu&quot;, wala makubaliano na &quot;usawa&quot;, bali ni mpango bora wa mkakati uliozingatia sheria za ulimwengu na hali halisi. Kupitia uanzishaji wa kwanza wa 20%, utamaduni wa usawa utapata nguvu na uzoefu wa kutosha, na mwishowe utaongoza maisha yote ya usawa kutekeleza lengo kuu la maendeleo pamoja ya kabila zote.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>17-位面至高强者标准 (Kiwango cha Watu Wenye Nguvu zaidi wa Mazingira)</li><li>22-资源分配联产承包机制 (Mfumo wa Mkataba wa Uzalishaji Pamoja kwa Mgawanyo wa Rasilimali)</li><li>75-20%激活战略实施 (Utekelezaji wa Mkakati wa Uanzishaji wa 20%)</li></ul>',39)])])}const y=i(w,[["render",o]]);export{z as __pageData,y as default};
